'use strict';
/* Cash feedback observes completed actions. It never changes game state or wraps G.act. */
(function(root){
const finite=n=>typeof n==='number'&&Number.isFinite(n),near=(a,b)=>Math.abs(a-b)<.5;
function analyze(state,ctx={}){const before=ctx.before||{},from=finite(before.cash)?before.cash:state.cash,to=state.cash,delta=to-from,ledger=Array.isArray(state.ledger)?state.ledger:[],hasHead=Object.prototype.hasOwnProperty.call(before,'ledgerHead');let rows=[],complete=false;
 if(hasHead){if(before.ledgerHead==null){rows=ledger.slice();complete=true;}else{const index=ledger.indexOf(before.ledgerHead);if(index>=0){rows=ledger.slice(0,index);complete=true;}else rows=[];}}
 const details=rows.map(row=>{const field=k=>row[k]==null?0:row[k],values=['gross','refund','supply','freight','cost'].map(field),safe=values.every(n=>finite(n)&&n>=0),incoming=safe?field('gross')+field('refund'):null,outgoing=safe?field('supply')+field('freight')+field('cost'):null;return {title:String(row.title||'Bokført oppgjør'),net:finite(row.net)?row.net:null,incoming,outgoing,reconciled:safe&&finite(row.net)&&near(incoming-outgoing,row.net)};});
 const known=details.filter(r=>r.net!==null).reduce((n,r)=>n+r.net,0),allKnown=details.every(r=>r.net!==null),reconciled=complete&&details.length>0&&allKnown&&details.every(r=>r.reconciled)&&near(known,delta),adjustment=allKnown?delta-known:null;
 return {from,to,delta,fromDay:finite(before.day)?before.day:state.day,toDay:state.day,days:finite(before.day)?Math.max(0,state.day-before.day):0,rows:details,complete,reconciled,incoming:reconciled?details.reduce((n,r)=>n+r.incoming,0):null,outgoing:reconciled?details.reduce((n,r)=>n+r.outgoing,0):null,known,adjustment,type:String(ctx.type||''),result:String(ctx.result||'')};
}
if(typeof module!=='undefined')module.exports={analyze};
if(!root.document)return;
const money={active:false,paused:false,timer:null,frame:null,entry:null},host=document.createElement('aside');host.id='moneyFeedback';host.className='money-feedback';host.hidden=true;host.setAttribute('aria-label','Siste oppgjør');document.body.append(host);
const text=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cash=n=>Math.round(n).toLocaleString('nb-NO')+' kr',signed=n=>(n>0?'+':n<0?'−':'')+cash(Math.abs(n)),day=d=>new Date(Date.UTC(2026,0,1+d)).toLocaleDateString('nb-NO',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}),motion=()=>localStorage.getItem('vestkyst-animations')!=='off'&&!matchMedia('(prefers-reduced-motion: reduce)').matches;
const title=type=>({tripBuy:'Reisekassa er endret',continueTrip:'Neste stopp på reisen',streetSell:'Salget er gjort opp',stockBuy:'Børskjøpet er bokført',stockSell:'Børssalget er bokført',advance:'Perioden er gjort opp',rest:'Byen går videre mens du hviler',crimeRest:'Et pusterom',questChoice:'Valget setter spor',coastChoice:'Møtet er gjort opp',crimeAttempt:'Jobben er gjort opp'})[type]||'Et nytt oppgjør';
function hide(){clearTimeout(money.timer);cancelAnimationFrame(money.frame);money.active=false;host.hidden=true;host.classList.remove('money-arrive');}
function finishMotion(){cancelAnimationFrame(money.frame);const e=money.entry;if(!e)return;const net=host.querySelector('[data-money-net]'),bar=host.querySelector('[data-money-time]'),skip=host.querySelector('[data-money-skip]');if(net)net.textContent=signed(e.delta);if(bar)bar.style.width='100%';if(skip)skip.hidden=true;host.classList.remove('money-arrive');host.classList.add('money-static');}
function schedule(){clearTimeout(money.timer);if(money.paused||host.matches(':hover')||host.contains(document.activeElement)||host.querySelector('details[open]'))return;money.timer=setTimeout(hide,4500);}
function togglePause(){money.paused=!money.paused;const b=host.querySelector('[data-money-pause]');if(b){b.textContent=money.paused?'Beholdes ✓':'Behold';b.setAttribute('aria-pressed',String(money.paused));}if(money.paused)clearTimeout(money.timer);else schedule();}
function detailHTML(e){const rows=e.rows.slice().reverse();return `<details class="money-details"><summary>Se hva som endret kassa</summary><div class="money-balances"><span>Før <b>${cash(e.from)}</b></span><span>Etter <b>${cash(e.to)}</b></span></div>${rows.length?`<div class="money-postings">${rows.map(r=>`<div><span>${text(r.title)}</span><b>${r.net===null?'Uspesifisert':signed(r.net)}</b></div>`).join('')}</div>`:'<p>Ingen nye, spesifiserte regnskapsposter ble knyttet til denne handlingen.</p>'}${!e.reconciled&&e.adjustment!==null&&!near(e.adjustment,0)?`<div class="money-adjustment"><span>${e.complete?'Annen endring i kassa, uten spesifisert postering':'Øvrig endring utenfor de viste posteringene'}</span><b>${signed(e.adjustment)}</b></div>`:''}${!e.complete?'<p>Posteringene er ikke et fullstendig oppgjør. Før- og ettersaldoen over viser hele kontantendringen.</p>':''}${e.type==='stockSell'?'<p>Salgsbeløpet er penger til kassa. Det er ikke det samme som aksjegevinst.</p>':''}${e.rows.length?'<p>Historisk vare- og aksjekostnad trekkes ikke fra kassa på nytt her.</p>':''}<button class="text-button" data-money-ledger>Åpne regnskapet →</button></details>`;}
function show(state,ctx){if(!finite(ctx.before?.cash)||!finite(state.cash))return;const e=analyze(state,ctx);if(near(e.delta,0)&&e.days===0)return;hide();money.entry=e;money.active=true;money.paused=false;const moving=motion();host.classList.toggle('money-static',!moving);host.innerHTML=`<div class="money-card"><div class="money-heading"><span class="section-kicker">${text(title(e.type))}</span><button class="money-close" data-money-hide aria-label="Skjul oppgjøret">×</button></div><span class="money-net-label">FAKTISK ENDRING I KASSA</span><strong class="money-net ${e.delta<0?'money-negative':e.delta>0?'money-positive':''}" data-money-net>${signed(e.delta)}</strong>${e.reconciled?`<div class="money-in-out"><span>Inn <b>+${cash(e.incoming)}</b></span><span>Ut <b>−${cash(e.outgoing)}</b></span></div>`:''}${e.days?`<div class="money-calendar"><div><b>${e.days} ${e.days===1?'dag':'dager'} gikk</b><button class="text-button" data-money-skip>Hopp over bevegelsen</button></div><span>${day(e.fromDay)} <i aria-hidden="true">→</i> ${day(e.toDay)}</span>${moving?'<div class="money-time-track"><i data-money-time></i></div>':''}${state.trip?`<small>${text(state.trip.remaining)} reisedager gjenstår.</small>`:state.event?'<small>En avgjørelse venter.</small>':''}</div>`:''}<div class="money-actions"><button class="text-button" data-money-pause aria-pressed="false">Behold</button><button class="text-button" data-money-ledger>Se regnskap →</button></div>${detailHTML(e)}</div>`;host.hidden=false;host.querySelector('[data-money-skip]')?.toggleAttribute('hidden',!moving);if(moving){host.classList.add('money-arrive');const start=performance.now(),duration=650;function frame(now){if(!money.active)return;const t=Math.min(1,(now-start)/duration),amount=Math.round(e.delta*(1-Math.pow(1-t,3))),net=host.querySelector('[data-money-net]'),bar=host.querySelector('[data-money-time]');if(net)net.textContent=signed(amount);if(bar)bar.style.width=(t*100)+'%';if(t<1)money.frame=requestAnimationFrame(frame);}money.frame=requestAnimationFrame(frame);}if(typeof exSound==='function')exSound();schedule();}
host.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-money-hide'))hide();if(b.hasAttribute('data-money-pause'))togglePause();if(b.hasAttribute('data-money-skip'))finishMotion();if(b.hasAttribute('data-money-ledger')){hide();view='ledger';render();window.scrollTo({top:0,behavior:'auto'});}});
host.addEventListener('pointerenter',()=>clearTimeout(money.timer));host.addEventListener('pointerleave',schedule);host.addEventListener('focusin',()=>clearTimeout(money.timer));host.addEventListener('focusout',()=>setTimeout(schedule,0));host.addEventListener('toggle',e=>{if(e.target.tagName==='DETAILS'){if(e.target.open)clearTimeout(money.timer);else schedule();}},true);
matchMedia('(prefers-reduced-motion: reduce)').addEventListener?.('change',e=>{if(e.matches)finishMotion();});
root.VestkystMoneyUI={analyze,show,hide,finishMotion,isActive:()=>money.active};
if(typeof G.on==='function')G.on('afterAction',show);
})(typeof window!=='undefined'?window:globalThis);
